  const start = safeTotal > 0 ? (safePage - 1) * safePageSize + 1 : 0

  start: fmtInt(start), end: fmtInt(Math.min(safePage * safePageSize, safeTotal)), total: fmtInt(safeTotal),
}) : totalKind === 'loaded' ? t('table.filter.loadedRowCount', '{{filtered}} matching / {{loaded}} loaded rows', {
